CREATE TYPE "EventStatus" AS ENUM ('DRAFT','PUBLISHED','CLOSED','FINISHED','CANCELLED');
CREATE TABLE "events" ("id" uuid PRIMARY KEY,"organizer_id" uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT ON UPDATE CASCADE,"public_slug" text NOT NULL UNIQUE,"title" text NOT NULL,"description" text NOT NULL,"type" text,"starts_at" timestamptz NOT NULL,"time_zone" text NOT NULL,"venue" text,"virtual_url" text,"status" "EventStatus" NOT NULL DEFAULT 'DRAFT',"primary_image_file_id" uuid REFERENCES stored_files(id) ON DELETE RESTRICT ON UPDATE CASCADE,"banner_image_file_id" uuid REFERENCES stored_files(id) ON DELETE RESTRICT ON UPDATE CASCADE,"gallery_file_ids" jsonb NOT NULL DEFAULT '[]',"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "event_benefits" ("id" uuid PRIMARY KEY,"event_id" uuid NOT NULL REFERENCES "events"("id") ON DELETE CASCADE,"kind" text NOT NULL,"name" text NOT NULL,"description" text,"image_file_id" uuid REFERENCES stored_files(id) ON DELETE RESTRICT ON UPDATE CASCADE,"condition" text,"position" integer NOT NULL DEFAULT 0);
CREATE INDEX "events_organizer_status_idx" ON "events"("organizer_id","status");

